// Probe 4: dump exactly which sK element lands in each bfrag slot of ldmatrix.x2
// for arbitrary (n-tile, k-step) offsets. sK holds index-encoded values:
// sK[row][col] = row*1000 + col, so loaded values identify source position.
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <stdio.h>
#include <stdint.h>

__device__ __forceinline__ void lds_x2(uint32_t r[2], const void* p) {
    uint32_t a = (uint32_t)__cvta_generic_to_shared(p);
    asm volatile("ldmatrix.sync.aligned.m8n8.x2.shared.b16 {%0,%1}, [%2];\n"
                 : "=r"(r[0]), "=r"(r[1]) : "r"(a));
}

constexpr int STRIDE = 136;

__global__ void probe4() {
    __shared__ __nv_bfloat16 sK[64][STRIDE];
    int t = threadIdx.x;
    for (int i = t; i < 64 * 128; i += 32) {
        int row = i / 128, col = i % 128;
        sK[row][col] = __float2bfloat16((float)(row * 1000 + col));
    }
    __syncthreads();

    int l = threadIdx.x % 32;
    // Addressing pattern: n-tile nt (key rows nt*8..), k-step ks (d ks*16..), per tile-var:
    // threads l=0..15 provide: matrix0 rows = sK[nt*8 + l][ks*16], matrix1 rows = sK[nt*8 + (l-8)][ks*16 + 8]
    int nt = 1, ks = 1;
    uint32_t b[2];
    lds_x2(b, &sK[nt * 8 + (l % 8)][ks * 16 + (l / 8) * 8]);
    if (t < 16) {
        uint16_t v[4];
        for (int i = 0; i < 2; i++) { v[2*i] = b[i] & 0xffff; v[2*i+1] = b[i] >> 16; }
        printf("nt=%d ks=%d lane %2d: b0=%d b1=%d b2=%d b3=%d (src rows sK[%d..], cols %d..)\n",
               nt, ks, l, v[0], v[1], v[2], v[3], nt * 8 + l, ks * 16 + (l / 8) * 8);
    }
    __syncthreads();
    // Same for nt=0,ks=0 to double-check base case across all lanes
    lds_x2(b, &sK[(l % 8)][(l / 8) * 8]);
    if (t < 16) {
        uint16_t v[4];
        for (int i = 0; i < 2; i++) { v[2*i] = b[i] & 0xffff; v[2*i+1] = b[i] >> 16; }
        printf("nt=0 ks=0 lane %2d: b0=%d b1=%d b2=%d b3=%d\n", l, v[0], v[1], v[2], v[3]);
    }
}

int main() {
    probe4<<<1, 32>>>();
    cudaDeviceSynchronize();
    cudaError_t e = cudaGetLastError();
    if (e) { printf("CUDA err: %s\n", cudaGetErrorString(e)); return 1; }
    return 0;
}

