// Attention forward kernel: FlashAttention-2 style with bf16 tensor cores
// (mma.sync.m16n8k16) on Ampere (sm_86). FP32 accumulation, online softmax.
//
// One block per (query tile, batch*head). BLOCK_M=64 query rows (4 mma m-tiles
// of 16), BLOCK_N=64 key rows (8 n-tiles of 8) per KV tile, 4 warps, head dim
// 128 = 8 mma k-steps of 16.
//
// Shared layout: K and Vt stored padded with 8 bf16 (272B rows) so that plain
// ldmatrix.x2 reads are bank-conflict-free:
//   sK[n][d]      (key rows x head dim)          -> QK^T B-fragment
//   sVt[d][n]     (transposed: head dim x key)   -> PV   B-fragment
// Q lives in registers as mma A-fragments (built from vectorized global loads).
//
// Softmax is handled at n-tile granularity (tile of 8 columns): after each
// QK^T mma, the 4-row x 8-col score tile in a warp is reduced by warp shuffles
// to produce per-row max/sum; P = exp(s - m) rescales O and updates l/m.

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_bf16.h>
#include <math.h>
#include <stdint.h>

namespace {

constexpr int BLOCK_M = 64;   // query rows per block
constexpr int BLOCK_N = 64;   // key/value rows per tile
constexpr int HEAD_DIM = 128;
constexpr int NUM_WARPS = 4;
constexpr int NUM_THREADS = NUM_WARPS * 32;
constexpr int MMA_M = 16;     // mma m16n8k16
constexpr int MMA_N = 8;
constexpr int MMA_K = 16;
constexpr int KSTEPS = HEAD_DIM / MMA_K;      // 8
constexpr int N_TILES = BLOCK_N / MMA_N;      // 8  (n-tiles per warp)
constexpr int M_TILES = BLOCK_M / MMA_M;      // 4  (m-tiles per warp)
constexpr int STRIDE = HEAD_DIM + 8;          // padded bf16 rows (272B)

// 16-byte vectorized global loads for Q rows; a warp reads 4 rows (lanes 0-3
// row 0, 4-7 row 1, ...) x 128 bf16 via 16B chunks (8 per row).
__device__ __forceinline__ void load_q_reg(
    uint32_t a_frag[M_TILES][4],  // per m-tile: 4 b32 regs (A fragment)
    const __nv_bfloat16* qbase, int grow0)
{
    const int lane = threadIdx.x % 32;
    // lane -> (row_in_group, 16B chunk): rows 0..3 per group of 4 lanes
    const int lr = lane / 4, lc = lane % 4;
#pragma unroll
    for (int mt = 0; mt < M_TILES; ++mt) {
        const int grow = grow0 + mt * MMA_M + lr;
        const uint4* p = reinterpret_cast<const uint4*>(
            qbase + (size_t)grow * HEAD_DIM + lc * 8);
        const __nv_bfloat16* pv = reinterpret_cast<const __nv_bfloat16*>(p);
        // Build A fragment for m-tile mt, k-step 0..7: this lane holds
        // (row lr, cols 2*lc, 2*lc+1) and (row lr+8, same cols) per k-step.
        uint32_t a[8];
#pragma unroll
        for (int ks = 0; ks < KSTEPS; ++ks) {
            const __nv_bfloat16* base = pv + ks * 16;
            // a0,a1 = (lr,  2lc),(lr,  2lc+1) | (lr+8, 2lc),(lr+8, 2lc+1)
            // a2,a3 = (lr,  2lc+8),(lr+8, 2lc+8) halves
            uint16_t e[4] = {
                __bfloat16_as_ushort(base[2 * lc]),
                __bfloat16_as_ushort(base[2 * lc + 1]),
                __bfloat16_as_ushort(base[8 + 2 * lc]),
                __bfloat16_as_ushort(base[8 + 2 * lc + 1]),
            };
            // (a0,a1) = rows (lr, lr+8) cols (2lc, 2lc+1)   [Figure 79]
            // (a2,a3) = rows (lr, lr+8) cols (2lc+8, 2lc+9)
            a[0] = e[0] | (e[1] << 16);   // wrong order? build carefully below
            a[1] = e[2] | (e[3] << 16);
            a[2] = 0; a[3] = 0;
