// A[r][k]: only one element set. B[k][0] = 2^k. Then D[0][0] reveals which k
// the hardware pairs with that A element.
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <stdio.h>
#include <stdint.h>

__global__ void k_probe(float* gD, int mode, int slot) {
    int lane = threadIdx.x % 32;
    int g = lane / 4, t = lane % 4;
