        for (int k = 0; k < 16; k++) B[k][0] = (float)(1 << k);
        int row = 0, col = 0;
        switch (slot) {
            case 0: row = g; col = 2*t; break;
            case 1: row = g; col = 2*t+1; break;
            case 2: row = g+8; col = 2*t; break;
            case 3: row = g+8; col = 2*t+1; break;
            case 4: row = g; col = 2*t+8; break;
            case 5: row = g; col = 2*t+9; break;
            case 6: row = g+8; col = 2*t+8; break;
            case 7: row = g+8; col = 2*t+9; break;
